// ECB mode of operation on top of the AES block cipher,
// mirroring pyaes.AESModeOfOperationECB's interface.

import { AES } from './aes.mjs';

export class AESModeOfOperationECB {
  // key: Uint8Array of 16 bytes.
  constructor(key) {
    this._aes = new AES(key);
  }

  // data: Uint8Array whose length is a multiple of 16.
  // Returns a new Uint8Array with the ciphertext.
  encrypt(data) {
    if (data.length % 16 !== 0) {
      throw new Error('Data length must be a multiple of 16 bytes');
    }
    const out = new Uint8Array(data.length);
    for (let off = 0; off < data.length; off += 16) {
      out.set(this._aes.encryptBlock(data.subarray(off, off + 16)), off);
    }
    return out;
  }

  // data: Uint8Array whose length is a multiple of 16.
  // Returns a new Uint8Array with the recovered plaintext.
  decrypt(data) {
    if (data.length % 16 !== 0) {
      throw new Error('Data length must be a multiple of 16 bytes');
    }
    const out = new Uint8Array(data.length);
    for (let off = 0; off < data.length; off += 16) {
      out.set(this._aes.decryptBlock(data.subarray(off, off + 16)), off);
    }
    return out;
  }
}

