// Reproduce Python's repr() of a bytes object, so that printing it
// matches CPython's `print(b'...')` output character for character.

export function pyBytesRepr(bytes) {
  // CPython picks single quotes unless the data contains a single quote
  // and no double quote, in which case it uses double quotes.
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === quoteCode || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

