// Minimal re-implementation of the argparse behavior used by the source
// script: two required string options (--key, --data), plus -h/--help.
// Mirrors CPython argparse's usage/error text and exit codes.

const OPTIONS = ['--key', '--data'];

function metavar(opt) {
  return opt.slice(2).toUpperCase();
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --key KEY --data DATA`;
}

export function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help   show this help message and exit',
    '  --key KEY',
    '  --data DATA',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function errorExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Parse argv (already stripped of node/script entries).
// Returns { key, data } or exits the process like argparse would.
export function parseArgs(prog, argv) {
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      printHelp(prog);
      process.exit(0);
    }

    let name = arg;
    let inlineValue = null;
    const eq = arg.indexOf('=');
    if (arg.startsWith('--') && eq !== -1) {
      name = arg.slice(0, eq);
      inlineValue = arg.slice(eq + 1);
    }

    // argparse allows unambiguous abbreviations of long options.
    let matched = null;
    if (OPTIONS.includes(name)) {
      matched = name;
    } else if (name.startsWith('--') && name.length > 2) {
      const candidates = OPTIONS.filter((o) => o.startsWith(name));
      if (candidates.length === 1) {
        matched = candidates[0];
      } else if (candidates.length > 1) {
        errorExit(prog, `ambiguous option: ${name} could match ${candidates.join(', ')}`);
      }
    }

    if (matched === null) {
      extras.push(arg);
      continue;
    }

    if (inlineValue !== null) {
      values[matched.slice(2)] = inlineValue;
    } else if (i + 1 < argv.length) {
      values[matched.slice(2)] = argv[++i];
    } else {
      errorExit(prog, `argument ${matched}: expected one argument`);
    }
  }

  if (extras.length > 0) {
    errorExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  const missing = OPTIONS.filter((o) => !(o.slice(2) in values)).map(metavar);
  if (missing.length > 0) {
    const names = OPTIONS.filter((o) => !(o.slice(2) in values)).join(', ');
    errorExit(prog, `the following arguments are required: ${names}`);
  }

  return values;
}

