// Port of /workspace/dataset/pyaes/test13.py to pure ESM Node.js.
// Round-trip AES-128 ECB encryption/decryption of a 16-byte string.

import { basename } from 'node:path';
import { AESModeOfOperationECB } from './ecb.mjs';
import { pyBytesRepr } from './pybytes.mjs';
import { parseArgs } from './argparse.mjs';

function main() {
  const prog = basename(process.argv[1] || 'test13.mjs');
  const args = parseArgs(prog, process.argv.slice(2));

  // Test round-trip encryption/decryption with ECB
  const key = Buffer.from(args.key, 'utf8'); // 16 bytes key
  const data = Buffer.from(args.data, 'utf8'); // 16 bytes data

  const aes = new AESModeOfOperationECB(key); // Initialize AES ECB cipher
  const ciphertext = aes.encrypt(data); // Encrypt plaintext
  const plaintext = aes.decrypt(ciphertext); // Decrypt ciphertext back
  console.log(pyBytesRepr(ciphertext));
  console.log(pyBytesRepr(plaintext));
}

main();

