cd /output
# Known-answer test: FIPS-197 AES-128 vector
node -e "import('./aes.mjs').then(({AES}) => {
  const key = Uint8Array.from(Buffer.from('000102030405060708090a0b0c0d0e0f','hex'));
  const pt  = Uint8Array.from(Buffer.from('00112233445566778899aabbccddeeff','hex'));
  const ct  = new AES(key).encryptBlock(pt);
  const ok  = Buffer.from(ct).toString('hex') === '69c4e0d86a7b0430d8cdb78070b4c55a';
  console.log('FIPS-197 vector:', ok ? 'PASS' : 'FAIL ' + Buffer.from(ct).toString('hex'));
});"
# Randomized round-trip + cross-check vs executable (quote/backslash/control-char heavy inputs)
fails=0
for i in $(seq 1 40); do
  key=$(head -c 200 /dev/urandom | tr -dc 'A-Za-z0-9!%&(),.:;<=>?_{}+-' | head -c 16)
  data=$(head -c 200 /dev/urandom | tr -dc "A-Za-z0-9!%&(),.:;<=>?_{}+-'" | head -c 16)
