  exp=$(/workspace/dataset/test13_executable --key "$key" --data "$data" 2>&1)
  act=$(node test13.mjs --key "$key" --data "$data" 2>&1)
  [ "$exp" = "$act" ] || { fails=$((fails+1)); echo "DIFF key=$key data=$data"; echo "exp: $exp"; echo "act: $act"; }
done
echo "randomized diffs: $fails"

